1220	  action: "alert",
1221	  duration_ms: 600000,
1222	  alert_channel_id: null,
1223	  alert_role_id: null,
1224	  lockdown_channels: [],
1225	  quarantine_new_joins: false,
1226	});
1227	
1228	export const defaultGate = (): DBModuleModerationGate => ({
1229	  enabled: false,
1230	  min_account_age_ms: 0,
1231	  require_avatar: false,
1232	  blocked_name_patterns: [],
1233	  action: "alert",
1234	  duration_ms: 0,
1235	  exempt_bots: true,
1236	  alert_channel_id: null,
1237	});
1238	
1239	/** Ventana por defecto de todos los límites del anti-nuke: 1 minuto. */
1240	export const NUKE_DEFAULT_WINDOW_MS = 60000;
1241	
1242	// Techo por acción. Las destructivas (borrar canales/roles/emojis, banear,
1243	// expulsar, purgar, crear webhooks) van más cortas que las que sólo crean o
1244	// editan; tocar el propio servidor es lo más raro de todo.
1245	const NUKE_DEFAULT_MAX: Record<ModerationNukeAction, number> = {
1246	  channel_delete: 3,
1247	  channel_create: 5,
1248	  channel_update: 5,
1249	  role_delete: 3,
1250	  role_create: 5,
1251	  role_update: 5,
1252	  member_ban: 3,
1253	  member_kick: 3,
1254	  member_prune: 3,
1255	  member_role_update: 5,
1256	  webhook_create: 3,
1257	  emoji_delete: 3,
1258	  guild_update: 2,
1259	};
1260	
1261	export const defaultNukeLimit = (
1262	  action: ModerationNukeAction,
1263	): DBModerationNukeLimit => ({
1264	  enabled: false,
1265	  max: NUKE_DEFAULT_MAX[action],
1266	  window_ms: NUKE_DEFAULT_WINDOW_MS,
1267	  punishment: "inherit",
1268	});
1269	
1270	export const defaultNukeLimits = (): Record<string, DBModerationNukeLimit> =>
1271	  Object.fromEntries(
1272	    MODERATION_NUKE_ACTIONS.map((action) => [action, defaultNukeLimit(action)]),
1273	  );
1274	
1275	export const defaultAntinuke = (): DBModuleModerationAntinuke => ({
1276	  enabled: false,
1277	  punishment: "strip_roles",
1278	  trusted_users: [],
1279	  trusted_roles: [],
1280	  watch_bots: true,
1281	  alert_channel_id: null,
1282	  alert_role_id: null,
1283	  limits: defaultNukeLimits(),
1284	});
1285	
1286	export const defaultLockdown = (): DBModuleModerationLockdown => ({
1287	  lock_message: "",
1288	  unlock_message: "",
1289	  bypass_roles: [],
1290	  server_channels: [],
1291	});
1292	
1293	// Mirror de `moduleModerationMock` del backend (api-db guild-mock.ts).
1294	export const defaultModerationValues: ModuleModerationSchema = {
1295	  // v4: añade `flows` (aditivo — array vacío es estado legítimo, así que el
1296	  // backfill de api-db-go comprueba PRESENCIA de la clave, no su valor; mismo
1297	  // criterio que `music` v8).
1298	  schema_version: 4,
1299	  enabled: false,
1300	  command_mode: "both",
1301	  commands_global: defaultCommandAccess(),
1302	  commands: createDefaultCommands(),
1303	  mute: { role_id: null, mode: "auto" },
1304	  log_channel_id: null,
1305	  track_native_actions: true,
1306	  automod: defaultAutomod(),
1307	  protection: defaultProtection(),
1308	  escalation: defaultEscalation(),
1309	  effects: defaultEffects(),
1310	  raid: defaultRaid(),
1311	  gate: defaultGate(),
1312	  antinuke: defaultAntinuke(),
1313	  lockdown: defaultLockdown(),
1314	  flows: [],
1315	};
1316	
1317	// 4º argumento de `normalizeModule`: se ejecuta sobre la MEZCLA (defaults +
1318	// documento) justo antes del `safeParse`. Existe por lo mismo que
1319	// `hydrateTempvoiceDefaults`: `deepMerge` NO fusiona elemento a elemento dentro
1320	// de un array, así que un peldaño de escalado guardado antes de que existiera un
1321	// campo llega aquí incompleto, el `safeParse` falla y `normalizeModule` devuelve
1322	// la mezcla en crudo — con la página entera detrás. Rellenar aquí arregla las
1323	// dos cosas: no hay `undefined` que leer y el parseo vuelve a pasar.
1324	export const hydrateModerationDefaults = (
1325	  merged: ModuleModerationSchema,
1326	): void => {
1327	  // Los `as Partial<…>` son a propósito: el tipo dice que los campos están, pero
1328	  // lo que llega de Mongo puede no tenerlos — es justo lo que hay que detectar.
1329	  for (const rule of merged.escalation?.rules ?? []) {
1330	    const draft = rule as Partial<DBModerationEscalationRule>;
1331	    const fallback = defaultEscalationRule();
1332	    if (draft.threshold == null) draft.threshold = fallback.threshold;
1333	    if (draft.action == null) draft.action = fallback.action;
1334	    if (draft.duration_ms == null) draft.duration_ms = fallback.duration_ms;
1335	  }
1336	  // `limits` es un mapa: las claves que el documento no traiga NO las repone
1337	  // `deepMerge` si el propio mapa viene sustituido, y una acción vigilada nueva
1338	  // (v3 trae trece) dejaría el select de la UI atado a un `undefined`.
1339	  const limits = merged.antinuke?.limits;
1340	  if (!limits) return;
1341	  for (const action of MODERATION_NUKE_ACTIONS) {
1342	    const current = limits[action];
1343	    if (current == null) {
1344	      limits[action] = defaultNukeLimit(action);
1345	      continue;
1346	    }
1347	    const draft = current as Partial<DBModerationNukeLimit>;
1348	    const fallback = defaultNukeLimit(action);
1349	    if (draft.enabled == null) draft.enabled = fallback.enabled;
1350	    if (draft.max == null) draft.max = fallback.max;
1351	    if (draft.window_ms == null) draft.window_ms = fallback.window_ms;
1352	    if (draft.punishment == null) draft.punishment = fallback.punishment;
1353	  }
1354	};
