import * as z from "zod";
import {
  dependencyRefiner,
  type FieldDependency,
} from "../form/hooks/dependencies";

// Tipos DB inlined. La versión publicada de `@kena/shared` (0.0.1) todavía no
// incluye el módulo moderation en su dist — la fuente de verdad es
// `libraries/library-shared/src/db/schemas/DBGuildSchemas.ts` (DBModuleModeration).
// `updated_at` (Date) lo gestiona el backend; se omite en el dashboard.

/** `only` = whitelist (solo estos ids), `all_except` = blacklist (todos menos estos). */
export interface DBAccessList {
  mode: "only" | "all_except";
  ids: string[];
}

/** Acceso de un comando: listas independientes para roles, canales y categorías. */
export interface DBCommandAccess {
  roles: DBAccessList;
  channels: DBAccessList;
  categories: DBAccessList;
}

/** Config por comando. `use_global: true` hereda `commands_global`. */
export interface DBConfigurableCommand {
  enabled: boolean;
  use_global: boolean;
  access: DBCommandAccess;
  /** Alias por prefijo (nombres alternativos que invocan el comando). */
  aliases: string[];
  /** Enviar un DM al usuario sancionado (solo aplica a comandos de sanción). */
  dm_enabled: boolean;
  /** Mensaje del DM (contenido + color). Admite variables. */
  dm_embed: DBModerationDmEmbed;
}

/** Mensaje del DM que recibe el usuario sancionado (por comando). Un solo campo rico;
 * para un "título" se usa un encabezado (`#`/`##`). */
export interface DBModerationDmEmbed {
  content: string;
  /** Color hex (#RRGGBB). `null` = color de acento del módulo. */
  color: string | null;
}

/** Comandos que notifican al usuario y por tanto exponen config de DM. */
export const MODERATION_SANCTION_COMMANDS = [
  "ban",
  "tempban",
  "kick",
  "mute",
  "tempmute",
  "avisar",
] as const;
export type ModerationSanctionCommand =
  (typeof MODERATION_SANCTION_COMMANDS)[number];

/** Etiquetas legibles de cada comando (para la UI del dashboard). */
export const MODERATION_COMMAND_LABELS: Record<string, string> = {
  ban: "Ban",
  tempban: "Ban temporal",
  unban: "Unban",
  kick: "Expulsar",
  mute: "Mute",
  tempmute: "Mute temporal",
  unmute: "Unmute",
  avisar: "Avisar",
  infrs: "Ver infracciones",
  modinf: "Editar infracción",
  delinf: "Borrar infracción",
  delinfs: "Borrar todas",
  limpiar: "Limpiar mensajes",
  lock: "Bloquear canal",
  unlock: "Desbloquear canal",
  slowmode: "Modo lento",
  vcmute: "Silenciar en voz",
  vcunmute: "Quitar silencio de voz",
  vcexpulsar: "Expulsar de voz",
  mover: "Mover de canal",
  nota: "Nota",
  caso: "Ver caso",
  raid: "Modo raid",
};

export const MODERATION_COMMANDS = [
  "ban",
  "tempban",
  "unban",
  "kick",
  "mute",
  "tempmute",
  "unmute",
  "avisar",
  "infrs",
  "modinf",
  "delinf",
  "delinfs",
  // v3: canal, voz, casos y modo raid.
  "limpiar",
  "lock",
  "unlock",
  "slowmode",
  "vcmute",
  "vcunmute",
  "vcexpulsar",
  "mover",
  "nota",
  "caso",
  "raid",
] as const;
export type ModerationCommand = (typeof MODERATION_COMMANDS)[number];

/** Uso de cada comando (en mono, estilo tempvoice). `<x>` obligatorio, `[x]` opcional. */
export const MODERATION_COMMAND_USAGE: Record<string, string> = {
  ban: "/ban <usuario> [razón]",
  tempban: "/tempban <usuario> <duración> [razón]",
  unban: "/unban <id_usuario> [razón]",
  kick: "/kick <usuario> [razón]",
  mute: "/mute <usuario> [razón]",
  tempmute: "/tempmute <usuario> <duración> [razón]",
  unmute: "/unmute <usuario> [razón]",
  avisar: "/avisar <usuario> [razón]",
  infrs: "/infrs <usuario>",
  modinf: "/modinf <caso> [duración] [razón]",
  delinf: "/delinf <caso>",
  delinfs: "/delinfs <usuario>",
  limpiar:
    "/limpiar <cantidad> [usuario] [contiene] [solo-bots] [solo-enlaces] [solo-adjuntos]",
  lock: "/lock [canal] [razón] [duración]",
  unlock: "/unlock [canal] [razón]",
  slowmode: "/slowmode <segundos> [canal]",
  vcmute: "/vcmute <usuario> [razón]",
  vcunmute: "/vcunmute <usuario>",
  vcexpulsar: "/vcexpulsar <usuario> [razón]",
  mover: "/mover <usuario> <canal>",
  nota: "/nota <usuario> <texto>",
  caso: "/caso <número>",
  raid: "/raid <activar|desactivar>",
};

/** Descripción de cada comando (subtítulo bajo el uso). */
export const MODERATION_COMMAND_DESC: Record<string, string> = {
  ban: "Banea a un usuario del servidor de forma permanente (aunque no esté en el servidor).",
  tempban: "Banea temporalmente a un usuario (aunque no esté en el servidor).",
  unban: "Quita el baneo a un usuario por su ID.",
  kick: "Expulsa a un usuario del servidor.",
  mute: "Silencia a un usuario indefinidamente (usa el rol de silencio).",
  tempmute:
    "Silencia temporalmente (aislamiento nativo ≤28 días, rol de silencio si es más).",
  unmute: "Quita el silencio a un usuario (aislamiento y/o rol).",
  avisar: "Añade un aviso al historial de un usuario.",
  infrs: "Muestra las infracciones de un usuario.",
  modinf: "Modifica la duración y/o la razón de una infracción.",
  delinf: "Elimina una infracción por su número de caso.",
  delinfs: "Elimina TODAS las infracciones de un usuario.",
  limpiar:
    "Borra mensajes recientes del canal, con filtros por usuario, contenido, bots, enlaces o adjuntos.",
  lock: "Bloquea el canal: @everyone deja de poder escribir (opcionalmente durante un tiempo).",
  unlock: "Desbloquea el canal y restaura los permisos que tenía antes.",
  slowmode: "Fija el modo lento del canal en segundos (`0` lo desactiva).",
  vcmute: "Silencia a un usuario en voz (silencio de servidor).",
  vcunmute: "Quita el silencio de voz a un usuario.",
  vcexpulsar: "Desconecta a un usuario del canal de voz en el que esté.",
  mover: "Mueve a un usuario a otro canal de voz.",
  nota: "Añade una nota privada al historial de un usuario (no se le avisa).",
  caso: "Muestra el detalle de una infracción por su número de caso.",
  raid: "Activa o desactiva a mano el modo raid del servidor.",
};

export const MODERATION_COMMAND_MODES = ["slash", "prefix", "both"] as const;
export type ModerationCommandMode = (typeof MODERATION_COMMAND_MODES)[number];

export const MODERATION_MUTE_MODES = ["auto", "timeout", "role"] as const;
export type ModerationMuteMode = (typeof MODERATION_MUTE_MODES)[number];

export interface DBModuleModerationMute {
  /** Rol de silencio. Necesario para mutes largos/indefinidos. `null` = sin configurar. */
  role_id: string | null;
  mode: ModerationMuteMode;
}

// ── AutoMod ────────────────────────────────────────────────────────────────

/** Acción al detectar una infracción de automod. Los tres primeros son los del
 * schema v2; `delete_kick`/`delete_ban` llegaron con el v3 (ampliación aditiva). */
export const AUTOMOD_ACTIONS = [
  "delete",
  "delete_warn",
  "delete_timeout",
  "delete_kick",
  "delete_ban",
] as const;
export type AutomodAction = (typeof AUTOMOD_ACTIONS)[number];

/** Reglas de automod (para iterar en la UI). Las tres primeras son del v2. */
export const AUTOMOD_RULES = [
  "mentions",
  "words",
  "invites",
  "spam",
  "duplicates",
  "caps",
  "links",
  "emojis",
  "attachments",
] as const;
export type AutomodRule = (typeof AUTOMOD_RULES)[number];

/** Campos comunes a todas las reglas (incl. exenciones propias por bloque). */
export interface DBAutomodRuleBase {
  enabled: boolean;
  action: AutomodAction;
  timeout_ms: number;
  /** Roles exentos de ESTA regla. */
  exempt_roles: string[];
  /** Canales exentos de ESTA regla. */
  exempt_channels: string[];
  /** Registrar además un aviso en el historial del autor, para que la infracción
   * sume al escalado automático. Independiente de `action`. */
  count_as_warn: boolean;
}

export interface DBAutomodMentionsRule extends DBAutomodRuleBase {
  blocked_users: string[];
  blocked_roles: string[];
  block_everyone: boolean;
  max_mentions: number;
}

export interface DBAutomodWordsRule extends DBAutomodRuleBase {
  words: string[];
  match_substring: boolean;
}

export interface DBAutomodInvitesRule extends DBAutomodRuleBase {
  allowed_codes: string[];
}

/** Flood de mensajes: más de `max_messages` del mismo autor en `window_ms`. */
export interface DBAutomodSpamRule extends DBAutomodRuleBase {
  max_messages: number;
  window_ms: number;
  /** Borrar toda la ráfaga que siga en la ventana, no sólo el último mensaje. */
  purge_burst: boolean;
}

/** Mensajes repetidos: el mismo contenido más de `max_repeats` veces. */
export interface DBAutomodDuplicatesRule extends DBAutomodRuleBase {
  max_repeats: number;
  window_ms: number;
}

/** Exceso de MAYÚSCULAS (sólo se evalúan los mensajes de `min_length` o más). */
export interface DBAutomodCapsRule extends DBAutomodRuleBase {
  min_length: number;
  /** Porcentaje máximo de letras en mayúscula (0-100). */
  max_percent: number;
}

/** Enlaces: con `block_all` se bloquea todo salvo `allowed_domains`; sin él,
 * sólo lo que esté en `blocked_domains`. */
export interface DBAutomodLinksRule extends DBAutomodRuleBase {
  block_all: boolean;
  allowed_domains: string[];
  blocked_domains: string[];
}

/** Spam de emojis (unicode + emojis personalizados del servidor). */
export interface DBAutomodEmojisRule extends DBAutomodRuleBase {
  max_emojis: number;
}

/** Adjuntos: cantidad máxima y extensiones prohibidas. */
export interface DBAutomodAttachmentsRule extends DBAutomodRuleBase {
  /** `0` = sin límite de cantidad. */
  max_attachments: number;
  /** Extensiones sin punto y en minúsculas (`exe`, `bat`, `scr`…). */
  blocked_extensions: string[];
}

export interface DBModuleModerationAutomod {
  mentions: DBAutomodMentionsRule;
  words: DBAutomodWordsRule;
  invites: DBAutomodInvitesRule;
  spam: DBAutomodSpamRule;
  duplicates: DBAutomodDuplicatesRule;
  caps: DBAutomodCapsRule;
  links: DBAutomodLinksRule;
  emojis: DBAutomodEmojisRule;
  attachments: DBAutomodAttachmentsRule;
}

// ── Protecciones (v3) ──────────────────────────────────────────────────────

/** Comprobaciones previas a CUALQUIER sanción. El dueño del servidor es siempre
 * inmune (no es configurable — Discord tampoco deja sancionarlo). */
export interface DBModuleModerationProtection {
  /** Roles cuyos portadores no pueden ser sancionados. */
  immune_roles: string[];
  /** Usuarios que no pueden ser sancionados. */
  immune_users: string[];
  /** Un moderador no puede sancionar a quien tenga un rol igual o superior. */
  respect_hierarchy: boolean;
  /** Roles que se saltan la comprobación de jerarquía (staff sénior). */
  hierarchy_bypass_roles: string[];
  /** No sancionar a quien tenga permiso de Administrador. */
  protect_admins: boolean;
  /** No sancionar a bots. */
  protect_bots: boolean;
  /** Permitir que un moderador se sancione a sí mismo. */
  allow_self_sanction: boolean;
}

// ── Escalado automático (v3) ───────────────────────────────────────────────

/** Sanción que aplica un peldaño del escalado. */
export const MODERATION_ESCALATION_ACTIONS = [
  "mute",
  "tempmute",
  "kick",
  "tempban",
  "ban",
] as const;
export type ModerationEscalationAction =
  (typeof MODERATION_ESCALATION_ACTIONS)[number];

/** Tipos de infracción que pueden sumar al contador del escalado. */
export const MODERATION_COUNTABLE_TYPES = [
  "warn",
  "note",
  "mute",
  "tempmute",
  "kick",
  "ban",
  "tempban",
] as const;
export type InfractionCountableType =
  (typeof MODERATION_COUNTABLE_TYPES)[number];

/** Un peldaño: al llegar a `threshold` infracciones se aplica `action`. */
export interface DBModerationEscalationRule {
  threshold: number;
  action: ModerationEscalationAction;
  /** Duración en ms para `tempmute` / `tempban`. Se ignora en el resto. */
  duration_ms: number;
}

export interface DBModuleModerationEscalation {
  enabled: boolean;
  /** Ventana de conteo en ms. `0` = cuenta todo el historial. */
  window_ms: number;
  /** Tipos de infracción que suman. Vacío = sólo `warn`. */
  count_types: InfractionCountableType[];
  /** Contar también las infracciones creadas por la auto-moderación. */
  count_automod: boolean;
  /** Al disparar un peldaño, empezar a contar de cero. */
  reset_after_trigger: boolean;
  /** Peldaños. Se aplica el de `threshold` más alto que se alcance. */
  rules: DBModerationEscalationRule[];
}

// ── Efectos de sanción (v3) ────────────────────────────────────────────────

/** `always` = siempre, `never` = nunca, `ask` = el comando expone la opción. */
export const MODERATION_EFFECT_POLICIES = ["always", "never", "ask"] as const;
export type ModerationEffectPolicy =
  (typeof MODERATION_EFFECT_POLICIES)[number];

export interface DBModerationEffect {
  policy: ModerationEffectPolicy;
  /** Valor por defecto de la opción del comando cuando `policy` es `ask`. */
  default: boolean;
}

export interface DBModuleModerationEffects {
  /** Desconectar del canal de voz al silenciar. */
  voice_disconnect_on_mute: DBModerationEffect;
  /** Aplicar además el silencio de servidor de voz. */
  server_mute_on_mute: DBModerationEffect;
  /** Quitar todos los roles al silenciar (se restauran al quitar el silencio). */
  strip_roles_on_mute: DBModerationEffect;
  /** Borrar el historial reciente de mensajes al banear. */
  purge_on_ban: DBModerationEffect;
  /** Ventana de borrado del ban, en segundos. Tope de Discord: 604800 (7 días). */
  purge_on_ban_seconds: number;
  /** Borrar los mensajes recientes al expulsar (best-effort). */
  purge_on_kick: DBModerationEffect;
  /** Ventana de borrado del kick, en segundos. */
  purge_on_kick_seconds: number;
  /** Borrar el mensaje que invocó el comando cuando se usa por prefijo. */
  delete_invocation: boolean;
  /** Responder a los comandos de barra sólo para el moderador (efímero). */
  ephemeral_replies: boolean;
}

// ── Anti-raid (v3) ─────────────────────────────────────────────────────────

export const MODERATION_RAID_ACTIONS = [
  "alert",
  "lockdown",
  "kick",
  "ban",
] as const;
export type ModerationRaidAction = (typeof MODERATION_RAID_ACTIONS)[number];

export interface DBModuleModerationRaid {
  enabled: boolean;
  /** Entradas necesarias dentro de la ventana para considerarlo una oleada. */
  join_threshold: number;
  join_window_ms: number;
  action: ModerationRaidAction;
  /** Duración del modo raid en ms. `0` = hasta desactivarlo a mano. */
  duration_ms: number;
  /** Canal donde avisar al staff. `null` = el canal de mod-log. */
  alert_channel_id: string | null;
  /** Rol al que mencionar en el aviso. `null` = sin mención. */
  alert_role_id: string | null;
  /** Canales que se bloquean con `lockdown`. Vacío = todos los de texto. */
  lockdown_channels: string[];
  /** Mientras el modo raid está activo, aplicar `action` a cada entrada nueva. */
  quarantine_new_joins: boolean;
}

// ── Filtro de entrada (v3) ─────────────────────────────────────────────────

export const MODERATION_GATE_ACTIONS = [
  "alert",
  "kick",
  "ban",
  "mute",
] as const;
export type ModerationGateAction = (typeof MODERATION_GATE_ACTIONS)[number];

export interface DBModuleModerationGate {
  enabled: boolean;
  /** Edad mínima de la cuenta en ms. `0` = sin mínimo. */
  min_account_age_ms: number;
  /** Rechazar cuentas sin foto de perfil. */
  require_avatar: boolean;
  /** Patrones prohibidos en el nombre (subcadena, sin distinguir mayúsculas). */
  blocked_name_patterns: string[];
  action: ModerationGateAction;
  /** Duración del silencio en ms cuando `action` es `mute`. `0` = indefinido. */
  duration_ms: number;
  /** No aplicar el filtro a bots. */
  exempt_bots: boolean;
  /** Canal donde avisar. `null` = el canal de mod-log. */
  alert_channel_id: string | null;
}

// ── Anti-nuke (v3) ─────────────────────────────────────────────────────────

/** Acciones destructivas vigiladas (se leen del registro de auditoría). */
export const MODERATION_NUKE_ACTIONS = [
  "channel_delete",
  "channel_create",
  "channel_update",
  "role_delete",
  "role_create",
  "role_update",
  "member_ban",
  "member_kick",
  "member_prune",
  "member_role_update",
  "webhook_create",
  "emoji_delete",
  "guild_update",
] as const;
export type ModerationNukeAction = (typeof MODERATION_NUKE_ACTIONS)[number];

/** Castigo global del anti-nuke. */
export const MODERATION_NUKE_PUNISHMENTS = [
  "alert",
  "strip_roles",
  "kick",
  "ban",
] as const;
export type ModerationNukePunishment =
  (typeof MODERATION_NUKE_PUNISHMENTS)[number];

/** Igual, más `inherit` = usar el castigo global (el de cada límite). */
export const MODERATION_NUKE_PUNISHMENTS_WITH_INHERIT = [
  ...MODERATION_NUKE_PUNISHMENTS,
  "inherit",
] as const;
export type ModerationNukePunishmentOrInherit =
  (typeof MODERATION_NUKE_PUNISHMENTS_WITH_INHERIT)[number];

/** Límite de una acción vigilada: como mucho `max` veces cada `window_ms`. */
export interface DBModerationNukeLimit {
  enabled: boolean;
  max: number;
  window_ms: number;
  /** `inherit` = el castigo global del bloque. */
  punishment: ModerationNukePunishmentOrInherit;
}

export interface DBModuleModerationAntinuke {
  enabled: boolean;
  /** Castigo por defecto de los límites que no traen el suyo. */
  punishment: ModerationNukePunishment;
  trusted_users: string[];
  trusted_roles: string[];
  /** Vigilar también a los bots (el caso para el que existe esto). */
  watch_bots: boolean;
  alert_channel_id: string | null;
  alert_role_id: string | null;
  /** Clave = `ModerationNukeAction`. Las ausentes se rellenan con su default
   * (ver `hydrateModerationDefaults`). */
  limits: Record<string, DBModerationNukeLimit>;
}

// ── Bloqueo de canales (v3) ────────────────────────────────────────────────

export interface DBModuleModerationLockdown {
  /** Mensaje que se publica al bloquear. Vacío = texto por defecto. Admite
   * `{reason}`, `{moderator}` y `{duration}`. */
  lock_message: string;
  /** Mensaje que se publica al desbloquear. Vacío = texto por defecto. */
  unlock_message: string;
  /** Roles que conservan el permiso de escribir en un canal bloqueado. */
  bypass_roles: string[];
  /** Canales del bloqueo de TODO el servidor. Vacío = todos los de texto. */
  server_channels: string[];
}

// ── Flujos de moderación (v4) ───────────────────────────────────────────────
// Espejo manual de `DBGuildSchemas.ts` (mismo motivo que el resto del
// fichero: la versión publicada de `@kena/shared` todavía no lo incluye).
// Se añaden aquí también las dos filas de Postgres (`DBModerationFlowRun`,
// `DBModerationFlowBlockCount`) — no cuelgan de `DBModuleModeration`, pero
// comparten fuente de verdad (contrato §1) y consumidor (`flows.server.ts`).
// El catálogo de bloques (disparadores/condiciones/pasos/variables) NO vive
// aquí: es `flows/catalog/` (mirror de `library-shared/src/moderation-flows`).

/** Cómo se combinan las condiciones de una rama. */
export type DBModerationFlowConditionMode = "and" | "or";

/** Por qué el motor NO ejecutó un flujo que sí encajaba con el disparador. */
export type DBModerationFlowBlockReason =
  | "cooldown" // cooldown por usuario del propio flujo
  | "rate_limit" // techo de ejecuciones por minuto del flujo
  | "channel_filter" // el canal (o su categoría) no pasa el scope
  | "role_filter" // el autor lleva un rol excluido por el scope
  | "bot_author" // autor bot y el flujo los ignora
  | "admin_author" // autor con permiso de gestión y el flujo los ignora
  | "trigger_filter" // los params del disparador no encajan
  | "missing_context" // Discord no mandó la pieza que el flujo necesita
  | "no_branch"; // ninguna rama pasó y no hay «si no» final

/** Resultado de una ejecución que SÍ llegó a correr pasos. */
export type DBModerationFlowRunStatus = "ok" | "partial" | "failed" | "blocked";

/** Dónde escucha el flujo y a quién ignora. Es el nodo «Scope & filters». */
export interface DBModerationFlowScope {
  /** Canales donde el flujo escucha. `all_except` + ids vacío = todos. */
  channels: DBAccessList;
  /** Categorías; se matchea el `parent_id` del canal del evento. */
  categories: DBAccessList;
  /** Roles del autor. `all_except` + ids = «roles ignorados». */
  roles: DBAccessList;
  /** Ignorar autores bot. Nace `true`: es el cortafuegos anti-bucle nº1. */
  ignore_bots: boolean;
  /** Ignorar a quien tenga ManageMessages/Administrator. Nace `true`. */
  ignore_admins: boolean;
  /** Cooldown POR USUARIO entre dos ejecuciones. 0 = sin cooldown. */
  cooldown_seconds: number;
  /** Techo de ejecuciones del flujo por minuto y guild. 0 = sin techo. */
  rate_limit_per_minute: number;
}

/** Una condición de una rama. `negate` es el interruptor «no». */
export interface DBModerationFlowCondition {
  id: string;
  /** Clave del catálogo `MODERATION_FLOW_CONDITIONS`. */
  type: string;
  negate: boolean;
  params: Record<string, unknown>;
}

/** Un paso: acción de moderación, `set_variable`, `wait` o `stop`. */
export interface DBModerationFlowStep {
  id: string;
  /** Clave del catálogo `MODERATION_FLOW_ACTIONS`. */
  type: string;
  params: Record<string, unknown>;
}

/** Rama alternativa. Sin condiciones = el «si no» final; debe ir ÚLTIMA. */
export interface DBModerationFlowBranch {
  id: string;
  condition_mode: DBModerationFlowConditionMode;
  conditions: DBModerationFlowCondition[];
  steps: DBModerationFlowStep[];
}

export interface DBModerationFlow {
  /** `crypto.randomUUID()`, estable de por vida (va en la URL del editor). */
  id: string;
  name: string;
  /** Sólo se ejecutan los `true`. Es el switch «Enabled» de la cabecera. */
  enabled: boolean;
  trigger: { type: string; params: Record<string, unknown> };
  scope: DBModerationFlowScope;
  /** Pasos previos a la bifurcación (típicamente `set_variable`). */
  setup: DBModerationFlowStep[];
  /** Condiciones de la rama RAÍZ (el «If» del editor). Vacío = siempre pasa. */
  condition_mode: DBModerationFlowConditionMode;
  conditions: DBModerationFlowCondition[];
  /** Pasos de la rama raíz (el `then`). */
  steps: DBModerationFlowStep[];
  /** Cadena `else if` / `else`. Ausente o vacío = sin ramas. */
  branches: DBModerationFlowBranch[];
  /**
   * Hasta cuándo se persiste CADA bloqueo como fila propia (ISO-8601).
   * `null` o pasado = sólo contadores agregados. Es el botón «Debug 15 min».
   */
  debug_until: string | null;
  created_at: string;
  updated_at: string;
}

/** Fila de RUNS (Postgres, `moderation.flow_runs`). Sólo lectura desde la
 *  dashboard — quien inserta es el bot. */
export interface DBModerationFlowRun {
  id: string;
  bot_id: string;
  guild_id: string;
  flow_id: string;
  status: DBModerationFlowRunStatus;
  /** Sólo cuando `status === "blocked"`. */
  blocked_reason: DBModerationFlowBlockReason | null;
  /** Id de la rama que ganó; `null` = la raíz. */
  branch_id: string | null;
  steps_total: number;
  steps_run: number;
  duration_ms: number;
  /** Código del primer paso fallido, p.ej. `missing_bot_permission`. */
  error_code: string | null;
  user_id: string | null;
  channel_id: string | null;
  /** Variables finales y resultado por paso. */
  metadata: Record<string, unknown>;
  created_at: string;
}

/** Recuento agregado de bloqueos, por (flujo, motivo, hora). */
export interface DBModerationFlowBlockCount {
  flow_id: string;
  reason: DBModerationFlowBlockReason;
  bucket: string;
  count: number;
}

export interface DBModuleModeration {
  schema_version: number;
  enabled: boolean;
  command_mode: ModerationCommandMode;
  commands_global: DBCommandAccess;
  commands: Record<string, DBConfigurableCommand>;
  mute: DBModuleModerationMute;
  log_channel_id: string | null;
  /** Registrar también las sanciones hechas directamente desde Discord (audit log). */
  track_native_actions: boolean;
  automod: DBModuleModerationAutomod;
  /** Protecciones previas a cualquier sanción (inmunidad y jerarquía). v3. */
  protection: DBModuleModerationProtection;
  /** Escalado automático por infracciones acumuladas. v3. */
  escalation: DBModuleModerationEscalation;
  /** Efectos secundarios de las sanciones (voz, roles, borrado). v3. */
  effects: DBModuleModerationEffects;
  /** Anti-raid: detección de oleadas de entradas. v3. */
  raid: DBModuleModerationRaid;
  /** Filtro de entrada (edad de cuenta, avatar, nombres). v3. */
  gate: DBModuleModerationGate;
  /** Anti-nuke: techo de acciones destructivas por actor y unidad de tiempo. v3. */
  antinuke: DBModuleModerationAntinuke;
  /** Bloqueo de canales (`/lock`, `/unlock` y el lockdown del anti-raid). v3. */
  lockdown: DBModuleModerationLockdown;
  /** Flujos de moderación configurables. v4. */
  flows: DBModerationFlow[];
}

// Inlined helper — equivalente a `createZodObject` de library-shared. El dist CJS
// publicado no lo expone como named export resoluble por el bundle de Vite.
type TypeToZod<T> = {
  [K in keyof T]: z.ZodType<T[K]> | z.ZodType<Exclude<T[K], undefined>>;
};
function createZodObject<T, S extends TypeToZod<T> = TypeToZod<T>>(obj: S) {
  return z.object(obj as Record<string, z.ZodType>) as unknown as z.ZodObject<S>;
}

